 min-width: 0;
 }
 .loan-cost-row > :first-child, .loan-schedule-row > :first-child, .loan-income-row > :first-child { min-width: 0; text-align: left; }
 .loan-cost-row > :last-child, .loan-schedule-row > :last-child, .loan-income-row > :last-child {
 text-align: right;
 font-variant-numeric: tabular-nums;
 white-space: nowrap;
 }
 .loan-terms > .d-flex { gap: 1rem; }
 .loan-terms strong, .loan-admin-facts strong, .loan-number, input[type=number] { text-align: right; font-variant-numeric: tabular-nums; }
 .loan-records .table .loan-number, .loan-operational-table .loan-number { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
 .loan-records .table .loan-number::before { text-align: left; white-space: normal; }
 @media (max-width: 360px) {
 .loan-cost-row, .loan-schedule-row, .loan-income-row { gap: .5rem; }
 }
 /* Application cards: applicant, financial details, status, then actions. */
 .loan-application-list { container-type: inline-size; display: grid; gap: .75rem; min-width: 0; }
 .loan-application-card { display: flex; flex-direction: column; gap: .85rem; min-width: 0; padding: 1rem; border: 1px solid var(--vf-light); border-radius: .8rem; }
 .loan-card-section { display: grid; gap: .65rem; min-width: 0; padding-bottom: .8rem; border-bottom: 1px solid var(--vf-light); }
 .loan-card-section-title { margin: 0; color: var(--vf-navy); font-size: .82rem; line-height: 1.35; font-weight: 800; }
 .loan-card-grid { display: grid; gap: .8rem 1rem; min-width: 0; align-items: start; }
 .loan-card-grid-two { grid-template-columns: repeat(2,minmax(0,1fr)); }
 .loan-card-grid-three { grid-template-columns: repeat(3,minmax(0,1fr)); }
 .loan-card-field { display: flex; flex-direction: column; align-items: flex-start; justify-content: flex-start; gap: .3rem; min-width: 0; }
 .loan-card-label { min-width: 0; color: var(--vf-navy); font-size: .75rem; line-height: 1.4; font-weight: 700; text-align: left; overflow-wrap: anywhere; }
 .loan-card-value { min-width: 0; color: var(--vf-navy); font-size: .875rem; line-height: 1.4; font-weight: 600; text-align: left; overflow-wrap: anywhere; }
 .loan-card-details { display: grid; gap: .2rem; min-width: 0; align-content: start; }

 @container (max-width: 350px) { .loan-card-grid-two { grid-template-columns: minmax(0,1fr); } }
 .loan-application-message { display: flex; align-items: center; flex-wrap: wrap; gap: .5rem; padding: .5rem .65rem; border: 1px solid var(--vf-light); border-radius: .6rem; background: var(--vf-background); font-size: .8rem; }
 .loan-application-status { display: inline-block; padding: .2rem .5rem; border-radius: 999px; font-weight: 700; white-space: nowrap; }
 .loan-status-pending { color: #8a4900; background: #fff0d3; }
 .loan-status-approved { color: #116534; background: #ddf5e5; }
 .loan-status-rejected { color: #a31c28; background: #fde4e6; }
 .loan-application-message { order: 1; }
 .loan-breakdown-button { margin-left: auto; padding: .25rem .45rem; font-size: .75rem; white-space: nowrap; transition: box-shadow .2s ease, transform .2s ease; }
 .loan-breakdown-button:hover { transform: translateY(-1px); }
 .loan-breakdown-button:active { transform: translateY(0); }
 body:has(#loanBreakdownModal.show) .modal-backdrop.show { background-color: #062b80; opacity: .48; backdrop-filter: blur(4px); }
 .loan-breakdown h3 { font-size: .95rem; font-weight: 800; margin: 0 0 .65rem; }
 .loan-financial-cards { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); align-items: start; gap: .875rem; margin-bottom: 1.25rem; }
 .loan-financial-card { min-width: 0; padding: 1.125rem; border: 1px solid var(--vf-light); border-radius: .75rem; background: #f7fbff; }
 .loan-financial-card h3 { margin: 0 0 .85rem; color: var(--vf-navy); }
 .loan-financial-rows { display: grid; gap: .7rem; margin: 0; }
 .loan-financial-rows > div { display: grid; grid-template-columns: minmax(0,1fr) max-content; align-items: baseline; gap: .75rem; min-width: 0; }
 .loan-financial-rows dt { min-width: 0; color: var(--wb-muted); font-size: .8rem; line-height: 1.35; font-weight: 600; overflow-wrap: anywhere; }
 .loan-financial-rows dd { margin: 0; color: var(--vf-navy); font-size: .85rem; line-height: 1.35; font-weight: 600; text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
 .loan-financial-rows .loan-financial-highlight { padding: .35rem .5rem; margin: -.35rem -.5rem; border-radius: .4rem; background: var(--vf-background); }
 .loan-financial-highlight :is(dt,dd), .loan-financial-total :is(dt,dd) { font-weight: 800; }
 .loan-financial-rows .loan-financial-total { padding-top: .7rem; border-top: 1px solid var(--vf-light); }
 .loan-breakdown-table { font-size: .82rem; table-layout: fixed; width: 100%; }
 .loan-breakdown-table :is(th,td) { padding: .5rem; vertical-align: middle; }
 .loan-breakdown-number { text-align: right; font-variant-numeric: tabular-nums; }
 .loan-breakdown-date { text-align: center; }
 .loan-breakdown-total { font-weight: 800; background: var(--vf-background); }
 .loan-breakdown-total > * { background-color: var(--vf-background) !important; }

 @media (max-width: 767.98px) {
 .loan-financial-cards { grid-template-columns: minmax(0,1fr); }
 #loanBreakdownModal .loan-breakdown-table { min-width: 0; max-width: 100%; }
 .loan-breakdown-table, .loan-breakdown-table tbody, .loan-breakdown-table tr, .loan-breakdown-table td { display: block; width: 100%; }
 .loan-breakdown-table thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
 .loan-breakdown-table tr { padding: .6rem; margin-bottom: .6rem; border: 1px solid var(--vf-light); border-radius: .6rem; }
 .loan-breakdown-table td { display: grid; grid-template-columns: minmax(0,1fr) minmax(0,1fr); gap: .6rem; padding: .2rem 0; border: 0; text-align: right; overflow-wrap: anywhere; }
 .loan-breakdown-table td::before { content: attr(data-label); text-align: left; font-weight: 700; }
 .loan-breakdown-table td.loan-breakdown-date { text-align: center; }
 .loan-breakdown-table tfoot { display: block; width: 100%; }
 .loan-breakdown-table tfoot tr { display: grid; grid-template-columns: minmax(0,1fr) auto; align-items: baseline; gap: .6rem; }
 .loan-breakdown-table tfoot :is(th,td) { display: block; width: auto; padding: .2rem 0; }
 .loan-breakdown-table tfoot td::before { content: none; }

 }
 @media (prefers-reduced-motion: reduce) { .loan-breakdown-button { transition: none; } .loan-breakdown-button:hover { transform: none; } }
 </style>
 <style>
 .income-upload-preview { padding: .75rem; border: 1px solid var(--vf-light); border-radius: .75rem; background: var(--vf-background); max-width: 34rem; }
 .income-upload-preview[hidden], .income-upload-preview [hidden] { display: none !important; }
 .income-preview-button { display: block; padding: 0; border: 0; background: transparent; text-align: left; cursor: zoom-in; }
 .income-preview-button img { display: block; max-width: 100%; max-height: 200px; border-radius: .5rem; object-fit: contain; }
 .income-upload-preview iframe { display: block; width: 100%; height: 220px; border: 1px solid var(--vf-light); border-radius: .5rem; background: white; }
 .income-quality-dialog { max-width: min(94vw, 1000px); max-height: 92vh; padding: 1rem; border: 1px solid var(--vf-light); border-radius: 1rem; color: var(--vf-navy); background: white; }
 .income-quality-dialog::backdrop { background: rgba(6,43,128,.5); backdrop-filter: blur(4px); }
 .income-quality-dialog img { display: block; max-width: 100%; max-height: 75vh; object-fit: contain; margin: auto; }
 .income-quality-dialog iframe { width: min(85vw, 900px); height: 75vh; border: 0; }
 .income-quality-dialog [hidden] { display: none !important; }
 </style>
 <style>
 .app-shell:not(.admin-dashboard) { --water-dark: var(--vf-navy); --water-teal: var(--vf-royal); --water-aqua: var(--vf-bright); --water-heading: var(--vf-navy); --water-muted: var(--vf-navy); }
 .app-shell:not(.admin-dashboard) .sidebar { background: linear-gradient(165deg, var(--vf-navy) 0%, var(--vf-navy) 52%, var(--vf-royal) 100%) !important; isolation: isolate; }
 .app-shell:not(.admin-dashboard) .sidebar::after { content: ''; position: absolute; z-index: -1; pointer-events: none; left: -55%; right: -45%; bottom: -28px; height: 125px; border-radius: 50% 48% 0 0; background: linear-gradient(165deg, rgba(22, 141, 255, .16) 0 35%, rgba(22, 141, 255, .24) 36% 68%, rgba(22, 141, 255, .13) 69%); }
 .app-shell:not(.admin-dashboard) .sidebar :is(.nav-link, .sidebar-brand, .sidebar-nav-toggle), .app-shell:not(.admin-dashboard) .sidebar .nav-link i { color: #fff !important; }
 .app-shell:not(.admin-dashboard) .sidebar :is(.nav-link, .sidebar-nav-row) { transition: background .2s ease, transform .2s ease, box-shadow .2s ease; }
 .app-shell:not(.admin-dashboard) .sidebar :is(.nav-link:hover, .sidebar-nav-row:hover) { background: rgba(22, 141, 255, .18); }
 .app-shell:not(.admin-dashboard) .sidebar :is(.nav-link.active, .sidebar-nav-row.active) { background: linear-gradient(110deg, var(--vf-royal), var(--vf-bright)) !important; box-shadow: 0 5px 14px rgba(6, 43, 128, .2); }
 .app-shell:not(.admin-dashboard) .sidebar-nav-row:is(.active, :hover) > .nav-link { background: transparent !important; box-shadow: none; }
 .app-shell:not(.admin-dashboard) .main-content { min-width: 0; background: linear-gradient(150deg, var(--vf-background) 0%, var(--vf-background) 55%, #f6fdff 100%); }
 .app-shell:not(.admin-dashboard) .content-wrapper { position: relative; isolation: isolate; animation: viaflow-water-entrance .4s ease-out both; }
 .app-shell:not(.admin-dashboard) .content-wrapper::before { content: ''; position: absolute; z-index: -1; top: 0; right: 0; width: min(38vw, 460px); height: 150px; pointer-events: none; background: radial-gradient(ellipse at 100% -30%, rgba(22, 141, 255, .15) 0 35%, transparent 36%), radial-gradient(ellipse at 100% -15%, rgba(7, 84, 200, .08) 0 48%, transparent 49%); }
 .app-shell:not(.admin-dashboard) :is(.page-heading h1, .panel-card h1, .panel-card h2, .panel-card h3, .dashboard-card h2, .dashboard-card h3, .announcement-card h2, .stat-value, .metric-value) { color: var(--vf-navy); }
 .app-shell:not(.admin-dashboard) :is(.page-heading p, .text-secondary, .form-text) { color: var(--vf-navy) !important; }
 .app-shell:not(.admin-dashboard) :is(.panel-card, .dashboard-card, .announcement-card, .billing-card, .dash-kpi) { min-width: 0; background: linear-gradient(145deg, #fff, #f7fdff) !important; border: 1px solid var(--vf-light) !important; border-radius: 16px !important; box-shadow: 0 8px 24px rgba(7, 84, 200, .10) !important; transition: box-shadow .2s ease, border-color .2s ease; }
 .app-shell:not(.admin-dashboard) :is(.dashboard-card, .announcement-card, .dash-kpi):hover { border-color: var(--vf-bright) !important; box-shadow: 0 13px 28px rgba(7, 84, 200, .16) !important; }
 .app-shell:not(.admin-dashboard) :is(.dashboard-card, .panel-card) :is(.feature-icon, .metric-icon) { background: linear-gradient(135deg, var(--vf-royal), var(--vf-bright)) !important; color: #fff !important; }
 .app-shell:not(.admin-dashboard) :is(.table, table) { --bs-table-bg: transparent; --bs-table-border-color: var(--vf-light); color: var(--vf-navy); }
 .app-shell:not(.admin-dashboard) :is(.table, table) thead th { background: var(--vf-background); color: var(--vf-navy); border-color: var(--vf-light); }
 .app-shell:not(.admin-dashboard) :is(.form-control, .form-select), body:has(.app-shell:not(.admin-dashboard)) .modal :is(.form-control, .form-select) { border-color: var(--vf-light); border-radius: .65rem; transition: border-color .2s ease, box-shadow .2s ease; }
 .app-shell:not(.admin-dashboard) :is(.form-control, .form-select):focus, body:has(.app-shell:not(.admin-dashboard)) .modal :is(.form-control, .form-select):focus { border-color: var(--vf-royal) !important; box-shadow: 0 0 0 .2rem rgba(22, 141, 255, .16) !important; }
 .app-shell:not(.admin-dashboard) .btn-primary, body:has(.app-shell:not(.admin-dashboard)) .modal .btn-primary { background: linear-gradient(120deg, var(--vf-navy), var(--vf-royal)) !important; border-color: var(--vf-royal) !important; color: #fff !important; }
 .app-shell:not(.admin-dashboard) .btn, body:has(.app-shell:not(.admin-dashboard)) .modal .btn { transition: background-color .2s ease, box-shadow .2s ease, border-color .2s ease; }
 .app-shell:not(.admin-dashboard) .btn:hover, body:has(.app-shell:not(.admin-dashboard)) .modal .btn:hover { box-shadow: 0 6px 14px rgba(6, 43, 128, .15); }
 body:has(.app-shell:not(.admin-dashboard)) .modal-content { border: 1px solid var(--vf-light) !important; border-radius: 16px !important; box-shadow: 0 16px 42px rgba(6, 43, 128, .18) !important; }
 body:has(.app-shell:not(.admin-dashboard)) .modal-title { color: var(--vf-navy); }
 .app-shell:not(.admin-dashboard) .page-link { color: var(--vf-navy); border-color: var(--vf-light); }
 .app-shell:not(.admin-dashboard) .page-item.active .page-link { color: #fff; background: var(--vf-royal); border-color: var(--vf-royal); }
 @keyframes viaflow-water-entrance { from { opacity: .98; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
 @media (max-width: 575.98px) { .app-shell:not(.admin-dashboard) .content-wrapper::before { width: 45%; height: 90px; } }
 @media (prefers-reduced-motion: reduce) { .app-shell:not(.admin-dashboard) .content-wrapper { animation: none !important; } .app-shell:not(.admin-dashboard) :is(.panel-card, .dashboard-card, .announcement-card, .sidebar .nav-link, .sidebar-nav-row, .btn, .form-control, .form-select) { transition: none !important; } }
 </style>
 <style>
 @media screen {
 :root { --viaflow-dark: var(--vf-navy); --viaflow-teal: var(--vf-royal); --viaflow-aqua: var(--vf-bright); --viaflow-heading: var(--vf-navy); --viaflow-muted: var(--vf-navy); --viaflow-border: var(--vf-light); --viaflow-shadow: 0 8px 24px rgba(7, 84, 200, .10); }
 .app-shell { --wb-primary: var(--viaflow-dark); --wb-primary-dark: var(--viaflow-dark); --wb-accent: var(--viaflow-teal); --wb-text: var(--viaflow-heading); --wb-muted: var(--viaflow-muted); --wb-border: var(--viaflow-border); }
 .app-shell :is(.consumer-stat, .reader-stat) { min-width: 0; background: linear-gradient(145deg,#fff,#f7fdff); border: 1px solid var(--viaflow-border); border-radius: 16px; box-shadow: var(--viaflow-shadow); transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease; }
 .app-shell :is(.consumer-stat, .reader-stat):hover { transform: translateY(-3px); border-color: var(--vf-bright); box-shadow: 0 13px 28px rgba(7, 84, 200, .16); }
 .app-shell :is(.consumer-stat-value, .reader-stat-value) { color: var(--viaflow-heading); overflow-wrap: anywhere; }
 .app-shell :is(.consumer-stat-label, .reader-stat-label) { color: var(--viaflow-muted); }
 .app-shell :is(.meter-queue-card, .meter-records-table) { border-color: var(--viaflow-border); background: #f7fdff; }
 .app-shell :is(.meter-queue-card, .meter-records-table) thead th { background: var(--vf-background); color: var(--viaflow-heading); border-color: var(--vf-light); }
 .app-shell :is(.meter-queue-card, .meter-records-table) tbody td { border-color: var(--vf-background); }
 .app-shell :is(.meter-focus-card, .meter-search-result) { background: linear-gradient(145deg,var(--vf-background),#fff); border-color: var(--viaflow-border); }
 .app-shell :is(.form-control, .form-select), .modal :is(.form-control, .form-select) { border-color: var(--vf-light); }
 .modal :is(.form-control, .form-select):focus { border-color: var(--viaflow-teal) !important; box-shadow: 0 0 0 .2rem rgba(22, 141, 255, .16) !important; }
 .modal-content, .reading-preview-card { border: 1px solid var(--viaflow-border) !important; border-radius: 16px !important; box-shadow: 0 16px 42px rgba(6, 43, 128, .18) !important; }
 .modal :is(.modal-title, .meter-reading-value, .reading-value), .reading-preview-card .reading-value { color: var(--viaflow-heading); }
 .modal :is(.meter-focus-card, .meter-search-result) { background: linear-gradient(145deg,var(--vf-background),#fff); border-color: var(--viaflow-border); }
 .modal .btn-primary { background: linear-gradient(120deg,var(--viaflow-dark),var(--viaflow-teal)) !important; border-color: var(--viaflow-teal) !important; color: #fff !important; }
 .app-shell .table-responsive { max-width: 100%; }
 @media (max-width: 767.98px) { .app-shell :is(.consumer-dashboard-grid, .reader-dashboard-grid) { grid-template-columns: repeat(2,minmax(0,1fr)); } }
 @media (max-width: 380px) { .app-shell :is(.consumer-dashboard-grid, .reader-dashboard-grid) { grid-template-columns: 1fr; } }
 @media (prefers-reduced-motion: reduce) { .app-shell :is(.consumer-stat, .reader-stat) { transition: none; } .app-shell :is(.consumer-stat, .reader-stat):hover { transform: none; } }
 }
 </style>


 <style>
 @media screen {
 :is(.resubmit-page, .reschedule-page, .disconnection-screen) { background: radial-gradient(ellipse at 100% 0,rgba(22, 141, 255, .15),transparent 42%),linear-gradient(150deg,var(--vf-background) 0%,var(--vf-background) 55%,#f6fdff 100%); }
 :is(.resubmit-shell, .reschedule-card, .disconnection-popup) { background: linear-gradient(145deg,#fff,#f7fdff); border: 1px solid var(--vf-light); border-radius: 16px; box-shadow: 0 8px 24px rgba(7, 84, 200, .10); }
 :is(.resubmit-page, .reschedule-page, .disconnection-screen) :is(h1,h2,h3) { color: var(--vf-navy); }
