 }

 :where(.dashboard-card, .panel-card, .announcement-card, .card, .dash-kpi):hover {
 border-color: color-mix(in srgb, var(--wb-primary) 28%, var(--wb-surface));
 box-shadow: 0 1rem 2.25rem rgba(7, 84, 200, 0.1);
 }

 :where(h1, h2, h3, h4, h5, h6) {
