 }

 :where(.btn) {
 border-radius: 0.75rem;
 font-weight: 700;
 transition: transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease, border-color 0.2s ease;
 }

 :where(.btn-primary, .btn-success, .btn-info) {
 background: var(--wb-primary);
 border-color: var(--wb-primary);
 color: var(--wb-surface);
 }

 :where(.btn-primary, .btn-success, .btn-info):hover,
 :where(.btn-primary, .btn-success, .btn-info):focus-visible {
 background: color-mix(in srgb, var(--wb-primary) 88%, var(--wb-text));
