 --bs-table-border-color: var(--wb-border);
 margin-bottom: 0;
 }

 :where(.table thead th) {
 padding: 0.8rem 1rem;
 background: color-mix(in srgb, var(--wb-primary) 6%, var(--wb-surface)) !important;
 color: var(--wb-muted) !important;
 font-size: 0.73rem;
 font-weight: 800;
 letter-spacing: 0.055em;
 text-transform: uppercase;
 white-space: nowrap;
 }

 :where(.table tbody td, .table tbody th) {
 padding: 0.85rem 1rem;
 vertical-align: middle;
 }

 :where(.table tbody tr) {
