 transition: transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease, border-color 0.2s ease;
 }

 :where(.btn-primary, .btn-success, .btn-info) {
 background: var(--wb-primary);
 border-color: var(--wb-primary);
 color: var(--wb-surface);
 }

 :where(.btn-primary, .btn-success, .btn-info):hover,
 :where(.btn-primary, .btn-success, .btn-info):focus-visible {
 background: color-mix(in srgb, var(--wb-primary) 88%, var(--wb-text));
 border-color: color-mix(in srgb, var(--wb-primary) 88%, var(--wb-text));
 box-shadow: 0 0.5rem 1.1rem color-mix(in srgb, var(--wb-primary) 20%, transparent);
 transform: translateY(-1px);
 }

 :where(.btn-outline-primary, .btn-outline-secondary) {
 border-color: var(--wb-border);
 color: var(--wb-primary);
 }

 :where(.table) {
 --bs-table-color: var(--wb-text);
 --bs-table-border-color: var(--wb-border);
 margin-bottom: 0;
 }

 :where(.table thead th) {
 padding: 0.8rem 1rem;
 background: color-mix(in srgb, var(--wb-primary) 6%, var(--wb-surface)) !important;
 color: var(--wb-muted) !important;
 font-size: 0.73rem;
 font-weight: 800;
 letter-spacing: 0.055em;
 text-transform: uppercase;
 white-space: nowrap;
 }

 :where(.table tbody td, .table tbody th) {
 padding: 0.85rem 1rem;
 vertical-align: middle;
 }

 :where(.table tbody tr) {
 transition: background-color 0.18s ease;
 }

 :where(.table tbody tr:hover) {
 background: color-mix(in srgb, var(--wb-primary) 3%, var(--wb-surface));
 }

 :where(.modal-content) {
 border: 1px solid var(--wb-border);
 border-radius: 1rem;
 box-shadow: 0 1.5rem 4rem rgba(6, 43, 128, 0.18);
 }

 :where(.modal-header, .modal-footer) {
 border-color: var(--wb-border);
 }

 :where(.modal-title) {
 color: var(--wb-text);
 font-weight: 800;
 }

 /* Bootstrap backdrops stay below the dialog, including stacked confirmations. */
 .modal-backdrop {
 background-color: rgba(6, 43, 128, 0.42);
 -webkit-backdrop-filter: blur(5px);
 backdrop-filter: blur(5px);
 }

 .modal-backdrop.fade {
 transition: opacity 0.25s ease;
 }

 .modal-backdrop.show {
 opacity: 1;
 }

 .modal-backdrop ~ .modal-backdrop {
 z-index: 1065;
 }

 #meterReadingSubmitConfirmModal,
 #duplicateReadingModal,
 #paymentSubmitConfirmModal {
 z-index: 1070;
 }

 .content-wrapper {
 animation: viaflow-content-in 0.32s ease-out both;
 opacity: 1;
 }

 @keyframes viaflow-content-in {
 from { opacity: 0; transform: translateY(6px); }
 to { opacity: 1; transform: translateY(0); }
 }

 @media (max-width: 767.98px) {
 .content-wrapper {
 padding: 0.9rem;
 }

 :where(.table-responsive) {
 border-radius: 0.75rem;
 }

 :where(.table-responsive .table) {
 min-width: 0;
 }

 :where(.table thead th, .table tbody td, .table tbody th) {
 padding: 0.7rem 0.75rem;
 }
 }

 @media (prefers-reduced-motion: reduce) {
 .modal-backdrop.fade { transition: none; }
 .content-wrapper,
 :where(.dashboard-card, .panel-card, .announcement-card, .card, .dash-kpi),
 :where(.btn),
 :where(.form-control, .form-select, .input-group-text) {
