 }

 }
 /* Consumer loan workspace */
 .loan-layout { display: grid; grid-template-columns: minmax(0, 1fr); align-items: start; gap: 1rem; width: 100%; margin: 0 0 1.5rem; }
 .loan-layout > div { display: block; min-width: 0; }
