 <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
 <script>
 document.addEventListener('DOMContentLoaded', function () {
 document.querySelectorAll('select[data-clearable-filter]').forEach(function (select, index) {
 if (!Array.from(select.options).some(function (option) { return option.hasAttribute('selected'); })) {
 select.selectedIndex = -1;
 }
 const defaults = {
 status: 'All Status', application_status: 'All Status', notice_status: 'All Status',
 channel: 'All Methods', payment_type: 'All Types', type: 'All Types',
 category: 'All Categories', month: 'All Months', year: 'All Years',
 membership: 'All Memberships', notice_membership: 'All Memberships'
 };
 const label = select.dataset.filterDefault || defaults[select.name];
 if (!label) return;
 const value = document.createElement('span');
 value.className = 'status-filter-value';
 value.id = 'filter-default-' + index;
 value.textContent = label;
 value.style.fontSize = window.getComputedStyle(select).fontSize;
 select.parentElement.classList.add('status-filter-display');
 select.insertAdjacentElement('afterend', value);
 const update = function () {
 const empty = select.selectedIndex < 0;
 value.hidden = !empty;
 if (empty) select.setAttribute('aria-describedby', value.id);
 else select.removeAttribute('aria-describedby');
 };
 select.addEventListener('change', update);
 update();
 });
 document.querySelectorAll('form[data-auto-filter]').forEach(function (form) {
 let timer = null;

 const clearTimer = function () {
 if (timer !== null) {
 window.clearTimeout(timer);
 timer = null;
 }
 };

 const submit = function () {
 clearTimer();

 if (typeof form.requestSubmit === 'function') {
 form.requestSubmit();
 } else {
 form.submit();
 }
 };

 const scheduleSubmit = function () {
 clearTimer();

 const configuredDelay = Number(form.dataset.autoFilterDebounce);
 const delay = Number.isFinite(configuredDelay) && configuredDelay >= 0
 ? configuredDelay
 : 450;

 timer = window.setTimeout(submit, delay);
 };

 form.querySelectorAll('select, input[type="month"], input[type="date"], input[type="week"], input[type="time"], input[type="checkbox"], input[type="radio"]').forEach(function (control) {
 control.addEventListener('change', submit);
 });

 form.querySelectorAll('input[type="search"], input[type="text"]').forEach(function (input) {
 input.addEventListener('input', scheduleSubmit);
 input.addEventListener('keydown', function (event) {
 if (event.key === 'Enter') {
 event.preventDefault();
 submit();
 }
 });
 });

 form.addEventListener('submit', clearTimer);

 form.querySelectorAll('a').forEach(function (link) {
 link.addEventListener('click', clearTimer);
 });

 document.addEventListener('click', function (event) {
 if (!form.contains(event.target)) {
 clearTimer();
 }
 }, true);

 window.addEventListener('pagehide', clearTimer);
 });
 });
 </script>
 <script>
 document.addEventListener('DOMContentLoaded', function () {
 const appShell = document.querySelector('.app-shell');
 const sidebar = document.getElementById('sidebarMenu');
 const collapseToggle = document.getElementById('sidebarCollapseToggle');
 const mobileToggle = document.getElementById('sidebarMobileToggle');
 const backdrop = document.getElementById('sidebarBackdrop');
 const mainContent = document.querySelector('.main-content');

 if (!appShell || !sidebar) {
 return;
 }

 const mobileQuery = window.matchMedia('(max-width: 991.98px)');
 const toggles = [collapseToggle, mobileToggle].filter(Boolean);

 const isMobile = function () {
 return mobileQuery.matches;
 };

 const isSidebarOpen = function () {
 return isMobile()
 ? appShell.classList.contains('sidebar-mobile-open')
 : !appShell.classList.contains('sidebar-collapsed');
 };

 const syncState = function () {
 const open = isSidebarOpen();

 toggles.forEach(function (toggle) {
 toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
 });

 if (collapseToggle) {
 const label = open ? 'Collapse sidebar' : 'Open sidebar';

 collapseToggle.setAttribute('aria-label', label);
 collapseToggle.setAttribute('title', label);
 }

 if (mobileToggle) {
 const label = open ? 'Close sidebar' : 'Open sidebar';

 mobileToggle.setAttribute('aria-label', label);
 mobileToggle.setAttribute('title', label);
 }

 sidebar.toggleAttribute('inert', isMobile() && !open);

 if (mainContent) {
 mainContent.toggleAttribute('inert', isMobile() && open);
 }
 };

 const openSidebar = function () {
 if (isMobile()) {
 appShell.classList.add('sidebar-mobile-open');
 } else {
 appShell.classList.remove('sidebar-collapsed');
 }

 syncState();

 const firstLink = sidebar.querySelector('.nav-link:not(.sidebar-subnav-link)')
 || sidebar.querySelector('.nav-link');

 if (isMobile() && firstLink) {
 window.setTimeout(function () {
 firstLink.focus();
 }, 0);
 }
 };

 const closeSidebar = function () {
 if (isMobile()) {
 appShell.classList.remove('sidebar-mobile-open');
 } else {
 appShell.classList.add('sidebar-collapsed');
 }

 syncState();

 const focusTarget = isMobile() && mobileToggle ? mobileToggle : collapseToggle;

 if (focusTarget) {
 window.setTimeout(function () {
 focusTarget.focus();
 }, 0);
 }
 };

 const toggleSidebar = function () {
 if (isSidebarOpen()) {
 closeSidebar();
 } else {
 openSidebar();
 }
 };

 toggles.forEach(function (toggle) {
 toggle.addEventListener('click', toggleSidebar);
 });

 sidebar.querySelectorAll('.sidebar-submenu-toggle').forEach(function (toggle) {
 toggle.addEventListener('click', function (event) {
 if (!isMobile() && appShell.classList.contains('sidebar-collapsed')) {
 const submenu = document.getElementById(toggle.getAttribute('aria-controls'));
 openSidebar();
 // An already-open submenu becomes visible as the rail expands.
 if (submenu && submenu.classList.contains('show')) event.stopPropagation();
 }
 });
 });

 if (backdrop) {
 backdrop.addEventListener('click', closeSidebar);
 }

 document.addEventListener('keydown', function (event) {
 if (event.key === 'Escape' && isMobile() && isSidebarOpen()) {
 closeSidebar();
 }
 });

 const handleBreakpointChange = function () {
 appShell.classList.remove('sidebar-mobile-open', 'sidebar-collapsed');
 syncState();
 };

 if (typeof mobileQuery.addEventListener === 'function') {
 mobileQuery.addEventListener('change', handleBreakpointChange);
 } else if (typeof mobileQuery.addListener === 'function') {
 mobileQuery.addListener(handleBreakpointChange);
 }

 syncState();
 });
 </script>
 <script>
 (() => {
 const dialog = document.getElementById('incomeProofDialog');
 const dialogImage = dialog?.querySelector('img');
 const dialogPdf = dialog?.querySelector('iframe');
 dialog?.querySelector('[data-close-income-dialog]')?.addEventListener('click', () => dialog.close());
 dialog?.addEventListener('keydown', (event) => { if (event.key === 'Escape') event.stopPropagation(); });
 dialog?.addEventListener('close', () => { dialogImage.removeAttribute('src'); dialogPdf.removeAttribute('src'); });
 function enlarge(url, pdf = false) {
 if (!dialog || !url) return;
 const activeModal = document.querySelector('.modal.show');
 (activeModal || document.body).append(dialog);
 dialogImage.hidden = pdf; dialogPdf.hidden = !pdf;
 (pdf ? dialogPdf : dialogImage).src = url;
 dialog.showModal();
 }
 async function assess(image) {
 if (!image.complete) await new Promise((resolve,reject)=>{image.addEventListener('load',resolve,{once:true});image.addEventListener('error',reject,{once:true})});
 const W=image.naturalWidth,H=image.naturalHeight;if(!W||!H)throw new Error('The image is unreadable or corrupted.');
 // Allow the checking indicator to paint before sampling original-resolution tiles.
 await new Promise(resolve => setTimeout(resolve, 0));
 const tile=128, cols=Math.ceil(W/tile),rows=Math.ceil(H/tile), stride=Math.max(1,Math.ceil(Math.sqrt(cols*rows/400)));
 const canvas=document.createElement('canvas');canvas.width=tile;canvas.height=tile;const ctx=canvas.getContext('2d',{willReadFrequently:true});if(!ctx)throw new Error('Image analysis is unavailable.');
 const regions=[];let globalL=0,globalN=0;
 for(let ty=0;ty<rows;ty+=stride)for(let tx=0;tx<cols;tx+=stride){
 const sx=tx*tile,sy=ty*tile,w=Math.min(tile,W-sx),h=Math.min(tile,H-sy);if(w<24||h<24)continue;
 ctx.clearRect(0,0,tile,tile);ctx.drawImage(image,sx,sy,w,h,0,0,w,h);const data=ctx.getImageData(0,0,w,h).data,g=new Float32Array(w*h),sat=new Uint8Array(w*h),hist=new Uint32Array(256);let sum=0;
 for(let i=0;i<g.length;i++){let k=i*4,a=data[k+3]/255,r=data[k]*a+255*(1-a),gr=data[k+1]*a+255*(1-a),b=data[k+2]*a+255*(1-a);let v=.299*r+.587*gr+.114*b;g[i]=v;hist[Math.round(v)]++;sum+=v;sat[i]=(Math.max(r,gr,b)-Math.min(r,gr,b)>75)?1:0;}
 globalL+=sum;globalN+=g.length;let lo=0,hi=255,cum=0;for(let k=0;k<256;k++){cum+=hist[k];if(cum>=g.length*.01){lo=k;break}}cum=0;for(let k=255;k>=0;k--){cum+=hist[k];if(cum>=g.length*.01){hi=k;break}}
 let n=0,strong=0,gradSum=0,lapSum=0,nx=0,ny=0,satEdge=0;const cells=new Set(),xbins=new Set(),ybins=new Set();
 for(let y=1;y<h-1;y+=2)for(let x=1;x<w-1;x+=2){let i=y*w+x,dx=Math.abs(g[i+1]-g[i-1])/2,dy=Math.abs(g[i+w]-g[i-w])/2,grad=Math.max(dx,dy);if(grad<7)continue;n++;gradSum+=grad;lapSum+=Math.abs(4*g[i]-g[i-1]-g[i+1]-g[i-w]-g[i+w]);if(grad>=35)strong++;if(dx>=7)nx++;if(dy>=7)ny++;satEdge+=sat[i];cells.add((Math.floor(y/16)*8)+Math.floor(x/16));xbins.add(Math.floor(x/8));ybins.add(Math.floor(y/8));}
 const pixels=Math.ceil((w-2)/2)*Math.ceil((h-2)/2),density=n/pixels,axis=Math.min(nx,ny)/Math.max(1,Math.max(nx,ny));
 if(n>=28 && density>.004 && density<.38 && cells.size>=3 && xbins.size>=3 && ybins.size>=2 && axis>.12 && satEdge/n<.7 && hi-lo>=12) regions.push({x:sx,y:sy,n,density,contrast:hi-lo,gradient:gradSum/n,strong:strong/n,lap:lapSum/n,mean:sum/g.length,axis});
 }
 const median=(arr)=>{arr.sort((a,b)=>a-b);return arr[Math.floor(arr.length/2)]||0};
 // Only tiles with distributed, two-directional, mostly neutral edges enter the score.
 // A decorative border, flat margin, or a single large line is not text evidence.
 const unable = ['Unable to Determine', 'The image could not be assessed confidently. Please inspect the full-size preview before submitting.', 'info'];
 if (Math.min(W,H) < 400) return ['Unable to Determine', 'The image resolution is low. Please inspect the full-size preview or choose a higher-resolution copy.', 'info'];
 if (regions.length < 2) {
 if (globalN && globalL/globalN < 15) return ['Poor Quality', 'The image appears extremely dark. Please consider replacing it.', 'danger'];
 return unable;
 }
 const gradient=median(regions.map(r=>r.gradient));
 const strong=median(regions.map(r=>r.strong));
 const detail=median(regions.map(r=>r.lap));
 const contrast=median(regions.map(r=>r.contrast));
 const brightness=median(regions.map(r=>r.mean));
 // Multiple independent measures must agree before issuing a blur warning.
 if (contrast >= 25 && gradient < 17 && strong < .04 && detail < 12)
 return ['Poor Quality', 'The content appears substantially blurred. Please inspect the full-size preview and consider replacing it.', 'danger'];
 if (contrast >= 25 && gradient < 30 && strong < .23 && detail < 35)
 return ['Possibly Blurry', 'Some content may be difficult to read. Please check the full-size preview.', 'warning'];
 if ((brightness < 45 || brightness > 250) && contrast < 35) return unable;
 if (contrast >= 35 && gradient >= 40 && strong >= .35 && detail >= 45)
 return ['Clear Image', 'Image quality appears sufficient for review.', 'success'];
 return unable;
 }
 function showQuality(node, result) { node.textContent=''; const badge=document.createElement('span'); badge.className='badge badge-soft-'+result[2]+' me-2'; const icon=document.createElement('i'); icon.className='bi '+({success:'bi-check-circle-fill',warning:'bi-exclamation-triangle-fill',danger:'bi-x-circle-fill'}[result[2]] || 'bi-info-circle')+' me-1'; icon.setAttribute('aria-hidden','true'); badge.append(icon, document.createTextNode(result[0])); node.append(badge, document.createTextNode(result[1])); }
 window.assessIncomeProof = async (img, status) => { status.textContent='Checking image quality…'; try { showQuality(status, await assess(img)); } catch (_) { showQuality(status, ['Unable to Determine', 'Please inspect the original carefully.', 'info']); } };
 window.openIncomeProofPreview = enlarge;
 document.querySelectorAll('[data-income-upload]').forEach(root => {
 const input=root.querySelector('input[type=file]'), preview=root.querySelector('[data-preview]'), metadata=root.querySelector('[data-metadata]'), img=root.querySelector('[data-image]'), pdf=root.querySelector('[data-pdf]'), zoom=root.querySelector('[data-enlarge]'), quality=root.querySelector('[data-quality]'), error=root.querySelector('[data-error]');
 let url=null, generation=0;
 root.querySelector('[data-replace]').addEventListener('click',()=>input.click());
 zoom.addEventListener('click',()=>enlarge(url));
 input.addEventListener('change', async () => {
 const version=++generation, file=input.files[0];
 if(url) URL.revokeObjectURL(url); url=null; img.removeAttribute('src'); pdf.removeAttribute('src'); preview.hidden=true; error.textContent=''; input.setCustomValidity('');
 if(!file) return;
 const ext=file.name.toLowerCase().split('.').pop();
 const fail=message=>{ if(version!==generation)return; error.textContent=message; input.setCustomValidity(message); preview.hidden=true; };
 if(!['jpg','jpeg','png','pdf'].includes(ext) || !['image/jpeg','image/png','application/pdf',''].includes(file.type)) return fail('Choose a JPG, PNG, or PDF file.');
 if(file.size>10*1024*1024 || !file.size) return fail('Choose a non-empty file no larger than 10 MB.');
 input.setCustomValidity('Please wait for the file check to finish.');
 preview.hidden=false; metadata.textContent=`${file.name} · ${ext.toUpperCase()} · ${(file.size/1024/1024).toFixed(2)} MB`; quality.textContent='Checking file…';
 try {
 if(ext==='pdf') {
 const head=new TextDecoder('latin1').decode(await file.slice(0,8).arrayBuffer()), tail=new TextDecoder('latin1').decode(await file.slice(Math.max(0,file.size-2048)).arrayBuffer());
 if(!head.startsWith('%PDF-') || !tail.includes('%%EOF') || !tail.includes('startxref')) throw new Error('The PDF is incomplete or unreadable.');
 if(version!==generation)return; url=URL.createObjectURL(file); pdf.src=url; pdf.hidden=false; zoom.hidden=true; quality.textContent='PDF preview available. Image quality is not automatically assessed for PDFs.';
 } else {
 url=URL.createObjectURL(file); pdf.hidden=true; zoom.hidden=false; img.src=url;
 try { const result=await assess(img); if(version!==generation)return; showQuality(quality,result); } catch (assessmentError) { if(version!==generation)return; if(!img.naturalWidth || !img.naturalHeight) throw assessmentError; showQuality(quality, ['Unable to Determine', 'Please inspect the full-size preview.', 'info']); }
 }
 if(version===generation) input.setCustomValidity('');
 } catch(e) { fail(e.message || 'This file could not be read.'); }
 });
 });
 })();
 </script>
 <script>
 document.addEventListener('DOMContentLoaded', function () {
 const form = document.getElementById('loanCreateForm');
 if (!form) return;
 const modal = document.getElementById('loanModal');
 const application = document.getElementById('loanApplicationStep');
 const terms = document.getElementById('loanTermsStep');
 const confirmation = document.getElementById('loanConfirmationStep');
 const accepted = document.getElementById('loan_terms_accepted');
 const token = document.getElementById('loan_confirmation_token');
 const term = document.getElementById('term_months');
 const next = document.getElementById('loanNextButton');
 const close = document.getElementById('loanCloseButton');
 const back = document.getElementById('loanTermsBackButton');
 const submit = document.getElementById('loanTermsSubmitButton');
 const cancel = document.getElementById('loanConfirmCancelButton');
 const confirm = document.getElementById('loanConfirmButton');
 const error = document.getElementById('loan_confirmation_error');
 let confirmed = false;
 let submitting = false;

 function showStep(step) {
 application.hidden = step !== 'application';
 terms.hidden = step !== 'terms';
 confirmation.hidden = step !== 'confirmation';
 close.hidden = step !== 'application';
 next.hidden = step !== 'application';
 back.hidden = step !== 'terms';
 submit.hidden = step !== 'terms';
 cancel.hidden = step !== 'confirmation';
 confirm.hidden = step !== 'confirmation';
 modal.querySelector('.modal-body').scrollTop = 0;
 }

 function updateTerms() {
 document.getElementById('loan_selected_agreement_term').textContent = term.value + ' months';
 }

 term.addEventListener('change', function () {
 accepted.checked = false;
 submit.disabled = true;
 token.value = '';
 updateTerms();
 });
 accepted.addEventListener('change', function () {
 submit.disabled = !accepted.checked;
 token.value = '';
 });
 next.addEventListener('click', function () {
 for (const field of application.querySelectorAll('input, select, textarea')) {
 if (!field.disabled && !field.checkValidity()) {
 field.reportValidity();
 return;
 }
 }
 updateTerms();
 showStep('terms');
 });
 back.addEventListener('click', () => showStep('application'));
 submit.addEventListener('click', function () {
 if (!accepted.checked || submitting) return;
 error.hidden = true;
 showStep('confirmation');
 });
 cancel.addEventListener('click', function () {
 if (!submitting) showStep('terms');
 });
 form.addEventListener('submit', function (event) {
 if (!confirmed || !token.value || !accepted.checked) event.preventDefault();
 });
 confirm.addEventListener('click', async function () {
 if (submitting || !accepted.checked) return;
 submitting = true;
 confirm.disabled = true;
 cancel.disabled = true;
 error.hidden = true;
 try {
 const response = await fetch('/loans/confirm-submission', {
 method: 'POST',
 credentials: 'same-origin',
 headers: { 'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': form.querySelector('[name="_token"]').value },
 body: JSON.stringify({ terms_accepted: 1, confirmed: 1, term_months: term.value }),
 });
 const result = await response.json();
 if (!response.ok || !result.confirmation_token) throw new Error('Unable to confirm the application. Please try again.');
 token.value = result.confirmation_token;
 confirmed = true;
 form.requestSubmit();
 } catch (exception) {
 submitting = false;
 confirm.disabled = false;
 cancel.disabled = false;
 error.textContent = exception.message || 'Unable to confirm the application. Please try again.';
 error.hidden = false;
 }
 });
 modal.addEventListener('hidden.bs.modal', function () {
 if (submitting) return;
 confirmed = false;
 token.value = '';
 showStep('application');
 });
 updateTerms();
 });
 </script>
 <script>
 (() => {
 const modal = document.getElementById('loanBreakdownModal');
 const body = document.getElementById('loanBreakdownBody');
 let request = null;
 modal?.addEventListener('show.bs.modal', async (event) => {
 const url = event.relatedTarget?.dataset.breakdownUrl;
 if (!url) { event.preventDefault(); return; }
 request?.abort(); request = new AbortController(); const activeRequest = request;
 body.textContent = 'Loading payment breakdown…';
 try {
 const response = await fetch(url, { credentials: 'same-origin', cache: 'no-store', signal: activeRequest.signal, headers: { 'X-Requested-With': 'XMLHttpRequest' } });
 if (!response.ok) throw new Error('Request failed');
 const content = await response.text();
 if (request === activeRequest) body.innerHTML = content;
 } catch (error) {
 if (error.name !== 'AbortError' && request === activeRequest) body.textContent = 'Unable to load this payment breakdown. Please close and try again.';
 }
 });
 modal?.addEventListener('hidden.bs.modal', () => { request?.abort(); request = null; body.textContent = ''; });
 })();
 </script>
 <script>
 document.addEventListener('DOMContentLoaded', function () {
 const termSelect = document.getElementById('term_months');
 const schedulePanel = document.querySelector('.loan-payment-schedule');
 const scheduleRows = document.getElementById('loanScheduleRows');
 const selectedTerm = document.getElementById('selectedLoanTerm');
 const estimatedMonthlyInstallment = document.getElementById('estimatedMonthlyInstallment');
 const scheduleTotal = document.getElementById('loanScheduleTotal');
 const loadingState = document.querySelector('.loan-breakdown-loading');
 const breakdownContent = document.querySelector('.loan-breakdown-content');
 const unavailableState = document.querySelector('.loan-breakdown-unavailable');

 if (!termSelect || !schedulePanel || !scheduleRows || !selectedTerm || !estimatedMonthlyInstallment || !scheduleTotal) {
 return;
 }

 const costsAvailable = schedulePanel.dataset.costsAvailable === 'true';
 const breakdown = JSON.parse(schedulePanel.dataset.loanBreakdown || '{}');
 const schedules = JSON.parse(schedulePanel.dataset.loanSchedules || '{}');
 const total = Number(schedulePanel.dataset.loanTotal || 0);
 const money = new Intl.NumberFormat('en-PH', {
 minimumFractionDigits: 2,
 maximumFractionDigits: 2,
 });

 const renderSchedule = () => {
 const term = termSelect.value;
 const rows = schedules[term] || [];
 const firstInstallment = rows.length > 0 ? Number(rows[0].amount || 0) : 0;

 selectedTerm.textContent = `${term} months`;
 estimatedMonthlyInstallment.textContent = `₱${money.format(firstInstallment)}`;
 scheduleRows.innerHTML = rows.map((row) => (
 `<div class="loan-schedule-row"><span>Month ${row.month}</span><strong>₱${money.format(Number(row.amount || 0))}</strong></div>`
 )).join('');
 scheduleTotal.textContent = `₱${money.format(total)}`;
 };

 window.setTimeout(() => {
 if (loadingState) {
 loadingState.hidden = true;
 }

 if (!costsAvailable) {
 if (unavailableState) {
 unavailableState.hidden = false;
 }
 termSelect.disabled = true;
 return;
 }

 document.getElementById('loanCostMeter').textContent = `₱${money.format(Number(breakdown.meter || 0))}`;
 document.getElementById('loanCostHose').textContent = `₱${money.format(Number(breakdown.hose || 0))}`;
 document.getElementById('loanCostOtherMaterials').textContent = `₱${money.format(Number(breakdown.other_materials || 0))}`;
 document.getElementById('loanCostTotal').textContent = `₱${money.format(total)}`;

 if (breakdownContent) {
 breakdownContent.hidden = false;
 }

 termSelect.addEventListener('change', renderSchedule);
 renderSchedule();
 }, 0);
 });
 </script>

 </body>
